//! Checked-in density-threshold SPIR-V (first real gen kernel).
//!
//! Ports `Shaper.fillChunk` (src/worldgen/v5/shaper.zig) bit-exactly: the
//! host stages CPU-computed q[825] f64 + 4 params, the GPU runs the whole
//! trilinear fill + stone/water/air select over 512 columns (LocalSize 64
//! -> 8 groups, 65536 u32 cells out).
//!
//! Source of truth is `threshold.comp.spvasm`. Regenerated by
//! `zig build shaders` (spirv-as + spirv-val); manual fallback:
//!
//!   spirv-as --target-env vulkan1.0 threshold.comp.spvasm -o threshold.comp.spv
//!   spirv-val --target-env vulkan1.0 threshold.comp.spv
//!
//! and commit both files. The binary embeds here via `@embedFile`, so the
//! dispatched bytes are bit-for-bit the validated assembler output.

const std = @import("std");

const bytes = @embedFile("threshold.comp.spv");

pub const word_count: usize = bytes.len / 4;

comptime {
    if (bytes.len % 4 != 0) @compileError("threshold.comp.spv size is not a whole word count");
}

/// Driver-ready u32 view (comptime-built from the embedded bytes).
pub const words: [word_count]u32 = blk: {
    @setEvalBranchQuota(10000);
    var w: [word_count]u32 = undefined;
    for (0..word_count) |i| {
        w[i] = std.mem.readInt(u32, bytes[i * 4 ..][0..4], .little);
    }
    break :blk w;
};

/// Contract (must match the shader source + `Shaper` constants):
/// input q density count, output cell count, groups at LocalSize 64.
pub const q_len: usize = 825;
pub const cells: usize = 16 * 256 * 16;
pub const columns: usize = 4 * 4 * 32;
pub const groups: u32 = columns / 64;
pub const q_bytes: usize = q_len * 8;
pub const out_bytes: usize = cells * 4;

/// Params SSBO layout: { sea_level, stone_id, water_id, air_id }.
pub const ParamWords = 4;

comptime {
    if (groups * 64 != columns) @compileError("columns must split into whole groups of 64");
}

test "threshold spv header is Vulkan 1.0 with Float64" {
    try std.testing.expectEqual(@as(u32, 0x07230203), words[0]);
    try std.testing.expectEqual(@as(u32, 0x00010000), words[1]);
    try std.testing.expectEqual(@as(usize, 940), word_count);
    // Capability Float64 (opcode 17, operand 10) must be present: without
    // it the f64 fill silently becomes garbage on strict drivers.
    // NoContraction (opcode 71, operand 42) must decorate every f64
    // arithmetic result: RADV fuses (q-d)*c into FMA without it, flipping
    // exact-zero comparisons (proven by the cell-16 knife-edge: 0.0 vs
    // 1-ulp-positive). If you regenerate the shader, keep both.
    var found_f64 = false;
    var nc_count: usize = 0;
    var i: usize = 5;
    while (i < word_count) {
        const w = words[i];
        const wc: usize = w >> 16;
        try std.testing.expect(wc >= 1);
        if (w == (@as(u32, 2) << 16) | 17) {
            try std.testing.expect(i + 1 < word_count);
            if (words[i + 1] == 10) found_f64 = true;
        }
        if (w == (@as(u32, 3) << 16) | 71) {
            try std.testing.expect(i + 2 < word_count);
            if (words[i + 2] == 42) nc_count += 1;
        }
        i += wc;
    }
    try std.testing.expectEqual(word_count, i);
    try std.testing.expect(found_f64);
    try std.testing.expectEqual(@as(usize, 22), nc_count);
}
